module.exports = {"schema":1,"revision":293,"topic_id":52,"topic_number":43,"pdf_source_name":"TEMA_41_INCENDIOS_DE_VEGETACION_E_INTERFAZ_URBANO_FORESTAL_PARA_INDEXAR.pdf","texts":[{"id":2900,"manual_page":"246","stem":"Un incendio avanza con una cabeza claramente definida y dos flancos activos. El sector próximo al punto de ignición conserva llamas visibles. ¿Qué deducción sobre el sector de mayor actividad se ajusta a las definiciones del manual?","options":["La cabeza identifica la dirección principal de propagación y suele concentrar mayor calor y actividad que los flancos.","La cola identifica la dirección principal de propagación y suele concentrar mayor calor y actividad que los flancos.","El origen identifica la dirección principal de propagación y coincide necesariamente con el frente más caliente.","El flanco situado a sotavento identifica por definición la dirección principal y el frente más caliente del incendio."],"correct_index":0,"explanation":"La cabeza es la zona más caliente y activa; el origen determina dónde comenzó el incendio, no dónde alcanza su máxima actividad.","question_family":"2026_RAZONAMIENTO","difficulty":"muy alta","kind":"texto","coverage_id":24980,"source_page":6,"old_correct_index":1,"old_stem_md5":"ed6007c936b364fd77f1ccdf04a776b0","source_evidence":"CEIS Guadalajara, Incendios de vegetación, página impresa 246: La cabeza es la zona más caliente y activa; el origen determina dónde comenzó el incendio, no dónde alcanza su máxima actividad."},{"id":2901,"manual_page":"246","stem":"Un reconocimiento identifica llamas en ambos laterales de un incendio alargado y un frente de avance claramente más intenso. ¿Cuál es la interpretación correcta de los laterales respecto al eje de propagación?","options":["Son la cola y el origen, y su posición es perpendicular al eje de propagación que marca el frente.","Son los flancos, aproximadamente paralelos a la propagación principal, con fuego activo potencialmente menos caliente que la cabeza.","Son dos cabezas secundarias, perpendiculares al eje de propagación y necesariamente más calientes que el frente.","Son bolsas laterales, aproximadamente paralelas al avance y constituidas siempre por combustible todavía no quemado."],"correct_index":1,"explanation":"Los flancos son los lados paralelos a la dirección principal; pueden tener actividad, normalmente menor que la cabeza.","question_family":"2026_RAZONAMIENTO","difficulty":"muy alta","kind":"texto","coverage_id":24981,"source_page":6,"old_correct_index":0,"old_stem_md5":"e16e9723232eab1efd30484506a25232","source_evidence":"CEIS Guadalajara, Incendios de vegetación, página impresa 246: Los flancos son los lados paralelos a la dirección principal; pueden tener actividad, normalmente menor que la cabeza."},{"id":2902,"manual_page":"246","stem":"La zona próxima al origen sigue ardiendo, pero su avance es mucho más lento que el del extremo opuesto del incendio. Atendiendo conjuntamente a posición y comportamiento, ¿cómo debe denominarse?","options":["Cabeza, por encontrarse próxima al lugar donde se inició el incendio y presentar combustión residual.","Flanco, por arder lentamente mientras que los extremos representan zonas principales de propagación.","Cola, por situarse frente a la cabeza, arder más despacio y hallarse a menudo próxima al origen.","Perímetro, porque cualquier tramo de intensidad decreciente se define por su proximidad al origen."],"correct_index":2,"explanation":"El manual describe la cola como la zona opuesta a la cabeza, de combustión generalmente más lenta y frecuentemente cercana al origen.","question_family":"2026_RAZONAMIENTO","difficulty":"muy alta","kind":"texto","coverage_id":24982,"source_page":6,"old_correct_index":3,"old_stem_md5":"b02fc8d662d3b007b162c23ecfd2f34a","source_evidence":"CEIS Guadalajara, Incendios de vegetación, página impresa 246: El manual describe la cola como la zona opuesta a la cabeza, de combustión generalmente más lenta y frecuentemente cercana al origen."},{"id":2903,"manual_page":"246","stem":"Durante la delimitación de un incendio se recorre un tramo de borde donde no se observan llamas ni brasas superficiales. ¿Qué conclusión es válida respecto al perímetro reconocido?","options":["El tramo deja de pertenecer al perímetro porque la línea límite exige combustión activa continua.","El tramo constituye una isla porque toda ausencia local de fuego se considera combustible interior intacto.","El tramo constituye necesariamente la cola porque el incendio solo puede apagarse en el sector opuesto a la cabeza.","El tramo puede seguir formando parte del perímetro: la línea límite incluye sectores sin fuego activo."],"correct_index":3,"explanation":"El perímetro es la línea límite o borde del incendio; no exige fuego activo a lo largo de toda ella.","question_family":"2026_RAZONAMIENTO","difficulty":"muy alta","kind":"texto","coverage_id":24983,"source_page":6,"old_correct_index":3,"old_stem_md5":"af04a6c61270615bec4603e2b5845862","source_evidence":"CEIS Guadalajara, Incendios de vegetación, página impresa 246: El perímetro es la línea límite o borde del incendio; no exige fuego activo a lo largo de toda ella."},{"id":2904,"manual_page":"246","stem":"En un flanco aparece una prolongación estrecha de fuego todavía unida al incendio principal. Una dotación trabaja entre esa prolongación y el cuerpo principal. ¿Qué denominación y riesgo recoge el manual?","options":["Dedo; su crecimiento puede flanquear al personal que trabaja entre la prolongación y el incendio principal.","Foco secundario; su crecimiento puede flanquear al personal porque permanece separado del perímetro principal.","Isla; su crecimiento puede flanquear al personal porque conserva combustible sin quemar completamente rodeado.","Bolsa; su crecimiento puede flanquear al personal porque constituye la propia prolongación incendiada."],"correct_index":0,"explanation":"El dedo es una franja estrecha conectada al incendio principal y puede flanquear a intervinientes; la bolsa es una zona sin quemar adyacente.","question_family":"2026_RAZONAMIENTO","difficulty":"muy alta","kind":"texto","coverage_id":24984,"source_page":6,"old_correct_index":0,"old_stem_md5":"30e0dc1fe40659e6356831b2f649e3bb","source_evidence":"CEIS Guadalajara, Incendios de vegetación, página impresa 246: El dedo es una franja estrecha conectada al incendio principal y puede flanquear a intervinientes; la bolsa es una zona sin quemar adyacente."},{"id":2905,"manual_page":"246","stem":"Dos superficies sin quemar se encuentran en situaciones distintas: una entre una lengua de fuego y el cuerpo principal, otra totalmente encerrada por el perímetro. ¿Cómo se clasifican, respectivamente?","options":["Isla y bolsa: la primera está limitada por el dedo y la segunda constituye combustible interior.","Bolsa e isla: la primera queda entre el dedo y el incendio principal y la segunda dentro del perímetro.","Bolsa y foco secundario: la primera queda entre dos frentes y el segundo permanece en el interior.","Dedo e isla: la primera corresponde al saliente de combustible intacto y la segunda al exterior."],"correct_index":1,"explanation":"La bolsa es combustible sin quemar entre el incendio principal y un dedo; la isla queda dentro del perímetro.","question_family":"2026_RAZONAMIENTO","difficulty":"muy alta","kind":"texto","coverage_id":24985,"source_page":6,"old_correct_index":0,"old_stem_md5":"920b3f0044e9510f7da44873e0d2eca7","source_evidence":"CEIS Guadalajara, Incendios de vegetación, página impresa 246: La bolsa es combustible sin quemar entre el incendio principal y un dedo; la isla queda dentro del perímetro."},{"id":2906,"manual_page":"246","stem":"Una pavesa provoca combustión en un punto situado por delante del incendio y separado de su línea límite. ¿Qué caracterización reúne simultáneamente el lugar de aparición y el mecanismo de formación?","options":["Isla interior formada por pavesas: permanece rodeada por el perímetro principal sin haber ardido previamente.","Bolsa exterior formada por pavesas: comunica necesariamente con el incendio principal por un dedo estrecho.","Foco secundario exterior: una partícula incandescente puede iniciar un área ardiente fuera del perímetro.","Flanco secundario exterior: la pavesa determina automáticamente un nuevo borde paralelo al avance principal."],"correct_index":2,"explanation":"Los focos secundarios están fuera del perímetro y pueden originarse por material incandescente transportado.","question_family":"2026_RAZONAMIENTO","difficulty":"muy alta","kind":"texto","coverage_id":24986,"source_page":6,"old_correct_index":0,"old_stem_md5":"4002c77771f5edaa3a5178c7967463a4","source_evidence":"CEIS Guadalajara, Incendios de vegetación, página impresa 246: Los focos secundarios están fuera del perímetro y pueden originarse por material incandescente transportado."},{"id":2907,"manual_page":"246","stem":"Un foco separado del incendio principal continúa creciendo hasta presentar cabeza, flancos y cola reconocibles. Días después ambos perímetros entran en contacto. ¿Cuál es la secuencia prevista en el manual?","options":["La aparición de partes propias impide por definición que se una posteriormente al incendio principal.","La unión posterior obliga a clasificar el foco inicial como una isla no quemada dentro del perímetro.","La aparición de partes propias transforma el área exterior en un dedo unido desde su origen.","Un foco secundario puede constituir un incendio independiente y acabar reuniéndose con el principal."],"correct_index":3,"explanation":"El texto admite que los focos secundarios crezcan como incendios propios y terminen uniéndose al principal.","question_family":"2026_RAZONAMIENTO","difficulty":"muy alta","kind":"texto","coverage_id":24987,"source_page":6,"old_correct_index":2,"old_stem_md5":"eafc6597d09806fb0fac13b499446d1e","source_evidence":"CEIS Guadalajara, Incendios de vegetación, página impresa 246: El texto admite que los focos secundarios crezcan como incendios propios y terminen uniéndose al principal."},{"id":2908,"manual_page":"246","stem":"Un mosaico de combustible permanece sin quemar en medio de una superficie completamente afectada. Aunque se desplaza la cabeza, ese mosaico sigue dentro de la línea límite. ¿Qué clasificación corresponde?","options":["Isla: zona interior del perímetro que conserva combustible no quemado, sin depender de su cercanía a la cabeza.","Bolsa: zona exterior al perímetro principal que solo existe entre dos focos secundarios independientes.","Dedo: zona interior sin quemar que sobresale hacia el frente y desplaza automáticamente la cabeza.","Foco secundario: zona interior sin quemar que procede del enfriamiento de una lengua de fuego."],"correct_index":0,"explanation":"La isla es un área de combustible no quemado dentro del perímetro; no depende de la posición relativa a cabeza o cola.","question_family":"2026_RAZONAMIENTO","difficulty":"muy alta","kind":"texto","coverage_id":24988,"source_page":6,"old_correct_index":1,"old_stem_md5":"69d955c8beccded4d6f3535c094e1285","source_evidence":"CEIS Guadalajara, Incendios de vegetación, página impresa 246: La isla es un área de combustible no quemado dentro del perímetro; no depende de la posición relativa a cabeza o cola."},{"id":2909,"manual_page":"246","stem":"Un incendio comenzó junto a una pista, mientras la cabeza actual se encuentra a considerable distancia tras varias horas de viento. ¿Qué afirmación relaciona correctamente ambos lugares?","options":["El origen deja de ser identificable cuando la cabeza supera por primera vez la posición de los flancos.","El origen permanece donde comenzó el fuego; la mayor actividad térmica puede desplazarse con la cabeza.","La cabeza permanece en el lugar de inicio, mientras que el origen se desplaza con la máxima velocidad.","El origen pasa a la cola solo si esta deja de mostrar llama activa en todo su recorrido."],"correct_index":1,"explanation":"El origen es el lugar inicial; cabeza, el sector más caliente y activo y dirección de propagación.","question_family":"2026_RAZONAMIENTO","difficulty":"muy alta","kind":"texto","coverage_id":24989,"source_page":6,"old_correct_index":2,"old_stem_md5":"135d09cdb916ad03566f5ddb5244e172","source_evidence":"CEIS Guadalajara, Incendios de vegetación, página impresa 246: El origen es el lugar inicial; cabeza, el sector más caliente y activo y dirección de propagación."},{"id":2910,"manual_page":"246","stem":"Durante la delimitación del perímetro y la búsqueda de focos nuevos, ¿qué afirmación sobre las zonas no quemadas es INCORRECTA?","options":["La línea del perímetro puede comprender tramos en los que no exista fuego activo.","Una isla puede permanecer sin quemar aun estando completamente dentro del perímetro.","Un foco secundario ocupa una superficie todavía no quemada situada dentro de la línea de perímetro.","Un foco secundario puede comenzar fuera del perímetro por transporte de material incandescente."],"correct_index":2,"explanation":"Es falsa la tercera: los focos secundarios son áreas ardientes exteriores al perímetro; las otras tres están descritas en el manual.","question_family":"2026_INCORRECTA","difficulty":"muy alta","kind":"texto","coverage_id":24990,"source_page":6,"old_correct_index":2,"old_stem_md5":"ae2cdef7c46736ba14339bbdfc911471","source_evidence":"CEIS Guadalajara, Incendios de vegetación, página impresa 246: Es falsa la tercera: los focos secundarios son áreas ardientes exteriores al perímetro; las otras tres están descritas en el manual."},{"id":2911,"manual_page":"246","stem":"En un incendio alargado, los laterales conservan combustión y la cabeza presenta un frente de mayor actividad. ¿Qué proposición combina correctamente la geometría y la intensidad?","options":["Los laterales son perpendiculares al avance y suelen presentar la misma temperatura que la cabeza.","Los laterales definen siempre la máxima temperatura por encontrarse en contacto continuo con la cola.","La cabeza es lateral a la propagación y los flancos definen la dirección principal de avance.","Los flancos son aproximadamente paralelos al avance y pueden arder sin alcanzar la intensidad de la cabeza."],"correct_index":3,"explanation":"La dirección principal la define la cabeza; los flancos son lados paralelos, con posible fuego activo menor que el de la cabeza.","question_family":"2026_RAZONAMIENTO","difficulty":"muy alta","kind":"texto","coverage_id":24991,"source_page":6,"old_correct_index":3,"old_stem_md5":"d0c40fa02ed8206cfe3e4857e6a58d75","source_evidence":"CEIS Guadalajara, Incendios de vegetación, página impresa 246: La dirección principal la define la cabeza; los flancos son lados paralelos, con posible fuego activo menor que el de la cabeza."},{"id":2912,"manual_page":"246","stem":"Una lengua estrecha de combustión sale del borde y limita un entrante de vegetación intacta. Un equipo debe identificar por separado la lengua, el entrante y el riesgo de quedar rodeado. ¿Qué combinación es correcta?","options":["Dedo, bolsa y posibilidad de flanqueo del personal por la extensión conectada.","Bolsa, dedo y posibilidad de flanqueo del personal por la zona no quemada.","Foco secundario, isla y flanqueo inevitable por una zona de ignición aislada.","Isla, bolsa y flanqueo exclusivamente por un foco que nace fuera del perímetro."],"correct_index":0,"explanation":"Dedo conectado, bolsa sin quemar entre dedo y principal, posible flanqueo por el dedo.","question_family":"2026_RAZONAMIENTO","difficulty":"muy alta","kind":"texto","coverage_id":24992,"source_page":6,"old_correct_index":2,"old_stem_md5":"2c69aa01f2ca73f588352d6803a37b62","source_evidence":"CEIS Guadalajara, Incendios de vegetación, página impresa 246: Dedo conectado, bolsa sin quemar entre dedo y principal, posible flanqueo por el dedo."},{"id":2913,"manual_page":"246","stem":"Se representa un combustible uniforme sobre terreno plano, sin dirección de viento apreciable. Al partir de un foco puntual, ¿qué combinación de forma y avance corresponde a las condiciones descritas?","options":["Elíptica; el frente se dirige preferentemente en un eje fijado por la pendiente regular del terreno.","Circular; el frente se propaga desde la zona central hacia el exterior en todas las direcciones.","Irregular; el frente desarrolla varios lóbulos porque la homogeneidad del combustible impide un círculo.","Elíptica; el frente mantiene dos cabezas opuestas aunque no exista viento ni pendiente irregular."],"correct_index":1,"explanation":"Terreno plano, combustible homogéneo y ausencia de viento caracterizan la progresión circular radial.","question_family":"2026_RAZONAMIENTO","difficulty":"muy alta","kind":"texto","coverage_id":24993,"source_page":6,"old_correct_index":1,"old_stem_md5":"4ffd0deeda71188c3fad20c8069e0918","source_evidence":"CEIS Guadalajara, Incendios de vegetación, página impresa 246: Terreno plano, combustible homogéneo y ausencia de viento caracterizan la progresión circular radial."},{"id":2914,"manual_page":"246","stem":"Un frente hipotético se desarrolla en ausencia de viento, sobre una llanura con combustible homogéneo. Sin introducir obstáculos ni cambios locales, ¿cuál es su pauta de avance?","options":["El crecimiento se orienta solo hacia el sector opuesto al origen aunque permanezca estable el ambiente.","El crecimiento se concentra en dos extremos longitudinales por una dirección predominante constante.","El crecimiento tiende a ser radial, desde la zona central hacia el exterior en todas direcciones.","El crecimiento adopta necesariamente lóbulos independientes porque la propagación es simultánea."],"correct_index":2,"explanation":"La forma circular avanza en todas las direcciones, desde la zona central hacia fuera.","question_family":"2026_RAZONAMIENTO","difficulty":"muy alta","kind":"texto","coverage_id":24994,"source_page":6,"old_correct_index":2,"old_stem_md5":"a840c9f30b8dceb07bb69f12d60c03db","source_evidence":"CEIS Guadalajara, Incendios de vegetación, página impresa 246: La forma circular avanza en todas las direcciones, desde la zona central hacia fuera."},{"id":2915,"manual_page":"246","stem":"Ante un incendio de progresión circular en terreno homogéneo, identifique la afirmación INCORRECTA sobre las condiciones del entorno.","options":["Un terreno plano es compatible con la propagación circular que presenta el manual.","Un combustible homogéneo permite que el frente se extienda radialmente en el patrón circular.","El frente del patrón circular puede avanzar desde el centro hacia el exterior en todas direcciones.","En terreno plano con combustible homogéneo, el viento predominante permite mantener la propagación circular."],"correct_index":3,"explanation":"La propagación circular descrita se produce sin viento; los otros tres enunciados son correctos.","question_family":"2026_INCORRECTA","difficulty":"muy alta","kind":"texto","coverage_id":24995,"source_page":6,"old_correct_index":1,"old_stem_md5":"1f96d6bf70cd7397c5d5789c67a5bec1","source_evidence":"CEIS Guadalajara, Incendios de vegetación, página impresa 246: La propagación circular descrita se produce sin viento; los otros tres enunciados son correctos."},{"id":2918,"manual_page":"246","stem":"En dos áreas planas con combustible homogéneo, una permanece sin viento y en la otra aparece viento de dirección estable. ¿Qué correspondencia entre condiciones y morfología del incendio es correcta?","options":["Sin viento, circular; con viento de dirección predominante, elíptica.","Sin viento, elíptica; con viento de dirección predominante, circular.","Sin viento, irregular; con viento de dirección predominante, circular.","Sin viento, elíptica; con viento de dirección predominante, irregular obligatoria."],"correct_index":0,"explanation":"El manual asocia forma circular a ausencia de viento y elíptica a dirección predominante sobre combustible homogéneo.","question_family":"2026_RAZONAMIENTO","difficulty":"muy alta","kind":"texto","coverage_id":24996,"source_page":6,"old_correct_index":1,"old_stem_md5":"749cf3b9b44719c92fc273d3d4d14af6","source_evidence":"CEIS Guadalajara, Incendios de vegetación, página impresa 246: El manual asocia forma circular a ausencia de viento y elíptica a dirección predominante sobre combustible homogéneo."},{"id":2920,"manual_page":"246","stem":"Se observa un contorno elíptico bien definido sobre terreno plano y combustible homogéneo. Sin introducir otros factores, ¿qué régimen eólico es coherente con ese patrón?","options":["Ausencia de viento, con avance radial equivalente en todas las direcciones desde el origen.","Viento con una dirección predominante que favorece la propagación preferente en un eje.","Alternancia continua de vientos opuestos que obliga a crear lóbulos en todos los flancos.","Viento variable y combustible heterogéneo como requisitos indispensables del contorno elíptico."],"correct_index":1,"explanation":"La forma elíptica se caracteriza por viento de una dirección predominante con combustible homogéneo.","question_family":"2026_RAZONAMIENTO","difficulty":"muy alta","kind":"texto","coverage_id":24997,"source_page":6,"old_correct_index":1,"old_stem_md5":"f291d51e5ed49c0006231cc7a991e646","source_evidence":"CEIS Guadalajara, Incendios de vegetación, página impresa 246: La forma elíptica se caracteriza por viento de una dirección predominante con combustible homogéneo."},{"id":2922,"manual_page":"246","stem":"Una propagación elíptica se mantiene mientras el frente atraviesa un tramo de relieve sin irregularidades marcadas. ¿Qué combinación de combustible y topografía mantiene las condiciones compatibles con ese patrón?","options":["Combustible heterogéneo y pendiente irregular, con oscilaciones continuas de la dirección del viento.","Combustible heterogéneo y terreno quebrado, aunque el viento gire alrededor de la cabeza.","Combustible homogéneo y terreno plano o pendiente regular bajo viento predominante.","Combustible homogéneo y pendientes alternas abruptas, siempre que el viento desaparezca."],"correct_index":2,"explanation":"El patrón elíptico admite terreno plano o pendiente regular y combustible homogéneo, con viento predominante.","question_family":"2026_RAZONAMIENTO","difficulty":"muy alta","kind":"texto","coverage_id":24998,"source_page":6,"old_correct_index":1,"old_stem_md5":"50470962f01a0f60dcfe4515e91b58cf","source_evidence":"CEIS Guadalajara, Incendios de vegetación, página impresa 246: El patrón elíptico admite terreno plano o pendiente regular y combustible homogéneo, con viento predominante."},{"id":2923,"manual_page":"246","stem":"Al comparar las morfologías circular, elíptica e irregular y sus condicionantes ambientales, ¿qué asociación es INCORRECTA?","options":["Circular: combustible homogéneo, terreno plano y ausencia de viento.","Elíptica: combustible homogéneo y viento de dirección predominante.","Irregular: variaciones de viento, heterogeneidad de combustible o pendientes irregulares.","Elíptica: combustible homogéneo, calma atmosférica y crecimiento radial de intensidad equivalente."],"correct_index":3,"explanation":"La cuarta asigna a la elíptica las condiciones de la circular; las otras tres se corresponden con el manual.","question_family":"2026_INCORRECTA","difficulty":"muy alta","kind":"texto","coverage_id":24999,"source_page":6,"old_correct_index":0,"old_stem_md5":"ce98f8ebf3d0d385afc701bf9a94b041","source_evidence":"CEIS Guadalajara, Incendios de vegetación, página impresa 246: La cuarta asigna a la elíptica las condiciones de la circular; las otras tres se corresponden con el manual."},{"id":2925,"manual_page":"246","stem":"En una zona plana de combustible homogéneo el viento pasa de calma a una dirección sostenida. ¿Cuál es la transformación morfológica más coherente sin añadir variabilidad de combustible o pendiente?","options":["De circular a elíptica, por incorporarse una dirección predominante del viento.","De elíptica a circular, porque el viento sostenido distribuye uniformemente el calor.","De circular a irregular necesariamente, aunque no existan variaciones de viento ni de relieve.","De elíptica a irregular necesariamente, porque todo viento con dirección fija crea lóbulos."],"correct_index":0,"explanation":"La variable que diferencia las formas circular y elíptica en esas condiciones es el viento predominante.","question_family":"2026_RAZONAMIENTO","difficulty":"muy alta","kind":"texto","coverage_id":25000,"source_page":6,"old_correct_index":1,"old_stem_md5":"9cff9e68dd1230db286057fc70490f42","source_evidence":"CEIS Guadalajara, Incendios de vegetación, página impresa 246: La variable que diferencia las formas circular y elíptica en esas condiciones es el viento predominante."},{"id":2926,"manual_page":"246","stem":"Un frente presenta múltiples salientes y entrantes. El análisis identifica variaciones de viento, sectores de combustible diferente y pendientes irregulares. ¿Cómo interpreta el manual esa morfología?","options":["Es un patrón circular determinado por la ausencia de una dirección de propagación principal.","Es un patrón irregular compatible con cualquiera de esos factores o con su acción conjunta.","Es un patrón elíptico que requiere mantener constantes todos los factores enumerados.","Es un patrón circular cuyo origen se halla obligatoriamente en cada entrante del perímetro."],"correct_index":1,"explanation":"La irregularidad puede obedecer a viento variable, heterogeneidad de combustible y/o pendientes irregulares.","question_family":"2026_RAZONAMIENTO","difficulty":"muy alta","kind":"texto","coverage_id":25001,"source_page":6,"old_correct_index":3,"old_stem_md5":"7b1af2f17b82d26a8009ad132bcdedeb","source_evidence":"CEIS Guadalajara, Incendios de vegetación, página impresa 246: La irregularidad puede obedecer a viento variable, heterogeneidad de combustible y/o pendientes irregulares."},{"id":2928,"manual_page":"246","stem":"Un incendio muestra lóbulos pronunciados pese a registrarse dirección e intensidad de viento relativamente constantes. ¿Qué explicación se ajusta al manual sin atribuirlo necesariamente a cambios del viento?","options":["La forma irregular exige que todo el viento local cambie constantemente de orientación.","La forma irregular indica siempre que el combustible es homogéneo y el terreno plano.","La heterogeneidad del combustible o un relieve con pendientes irregulares pueden explicar los lóbulos.","La continuidad de la dirección del viento excluye toda irregularidad de forma, incluso con cambios del terreno."],"correct_index":2,"explanation":"Las formas irregulares pueden depender del combustible heterogéneo y de la topografía, aunque no cambie el viento.","question_family":"2026_RAZONAMIENTO","difficulty":"muy alta","kind":"texto","coverage_id":25002,"source_page":6,"old_correct_index":0,"old_stem_md5":"36c686b7d769a48443e7017ac996f441","source_evidence":"CEIS Guadalajara, Incendios de vegetación, página impresa 246: Las formas irregulares pueden depender del combustible heterogéneo y de la topografía, aunque no cambie el viento."},{"id":2930,"manual_page":"246","stem":"Al valorar viento, combustible y pendiente como causas de un perímetro irregular, ¿qué afirmación es INCORRECTA?","options":["Las oscilaciones en la intensidad del viento pueden contribuir a una forma irregular.","Los cambios en la dirección del viento pueden contribuir a una forma irregular.","Un relieve con pendientes irregulares puede contribuir a una forma irregular.","La irregularidad se asocia a terreno plano, combustible homogéneo y ausencia de viento local."],"correct_index":3,"explanation":"La cuarta atribuye a una forma irregular las condiciones típicas de circular; las otras tres constan como causas.","question_family":"2026_INCORRECTA","difficulty":"muy alta","kind":"texto","coverage_id":25003,"source_page":6,"old_correct_index":0,"old_stem_md5":"08c743cc15f49a2931745afb3fb4d83c","source_evidence":"CEIS Guadalajara, Incendios de vegetación, página impresa 246: La cuarta atribuye a una forma irregular las condiciones típicas de circular; las otras tres constan como causas."},{"id":2932,"manual_page":"246","stem":"Durante una inspección aparecen tres áreas pequeñas de fuego aisladas varios metros por delante del frente principal, y se observó transporte de pavesas. ¿Cuál es la lectura conjunta más fundada?","options":["Son focos secundarios originados fuera del perímetro por material incandescente y pueden evolucionar independientemente.","Son islas originadas fuera del perímetro por material incandescente y permanecen siempre sin quemar.","Son bolsas originadas fuera del perímetro por material incandescente y deben conectar con un dedo.","Son flancos originados fuera del perímetro por material incandescente y conservan la dirección principal."],"correct_index":0,"explanation":"Las pavesas pueden iniciar focos secundarios fuera del perímetro, susceptibles de crecimiento propio.","question_family":"2026_RAZONAMIENTO","difficulty":"muy alta","kind":"texto","coverage_id":25004,"source_page":6,"old_correct_index":0,"old_stem_md5":"dbc712253301b36180c6d3368de88e9e","source_evidence":"CEIS Guadalajara, Incendios de vegetación, página impresa 246: Las pavesas pueden iniciar focos secundarios fuera del perímetro, susceptibles de crecimiento propio."},{"id":2934,"manual_page":"246","stem":"Un foco exterior desarrolla una cabeza reconocible y avanza hacia el cuerpo del incendio que lo originó. ¿Cuál es el desenlace contemplado por el manual sin alterar su clasificación inicial?","options":["El foco se transforma en isla cuando adquiere flancos, permaneciendo siempre dentro de su perímetro.","El foco puede crecer como incendio independiente y terminar uniéndose al principal del que procede.","El foco se convierte en bolsa por presentar cabeza propia, quedando entre dos dedos conectados.","El foco conserva obligatoriamente su aislamiento y nunca se une al incendio que le dio origen."],"correct_index":1,"explanation":"Los focos secundarios pueden llegar a ser grandes incendios independientes y finalmente unirse al principal.","question_family":"2026_RAZONAMIENTO","difficulty":"muy alta","kind":"texto","coverage_id":25005,"source_page":6,"old_correct_index":2,"old_stem_md5":"f2162ae9ff4056f11a0620f28924893e","source_evidence":"CEIS Guadalajara, Incendios de vegetación, página impresa 246: Los focos secundarios pueden llegar a ser grandes incendios independientes y finalmente unirse al principal."},{"id":2936,"manual_page":"246","stem":"Durante la búsqueda de focos y el reconocimiento de lenguas de fuego, ¿qué descripción de estos elementos es INCORRECTA?","options":["Un foco secundario puede comenzar por material incandescente fuera del perímetro principal.","Un dedo es una extensión estrecha del incendio principal y puede flanquear al personal.","Un foco secundario es una mancha de combustible intacto completamente encerrada por el perímetro.","Una isla es combustible sin quemar ubicado dentro del perímetro del incendio."],"correct_index":2,"explanation":"Se corrige el error del banco anterior: la tercera es falsa; describe incorrectamente el foco como isla interior.","question_family":"2026_INCORRECTA","difficulty":"muy alta","kind":"texto","coverage_id":25006,"source_page":6,"old_correct_index":0,"old_stem_md5":"e0fc682f6c2115d93b8d576e79dfd2bc","source_evidence":"CEIS Guadalajara, Incendios de vegetación, página impresa 246: Se corrige el error del banco anterior: la tercera es falsa; describe incorrectamente el foco como isla interior."},{"id":2937,"manual_page":"246","stem":"Un equipo se desplaza por un flanco y detecta una franja de llama estrecha que parte del incendio y puede situarse a su espalda. ¿Qué elemento identifica el manual y qué implicación tiene?","options":["Isla, cuyo avance hacia el exterior del perímetro puede cerrar la salida del equipo.","Bolsa, cuya combustión interna constituye siempre el sector más caliente.","Foco secundario, necesariamente unido al principal desde el momento de su inicio.","Dedo, extensión conectada que puede flanquear a intervinientes en esa posición."],"correct_index":3,"explanation":"La prolongación estrecha conectada es un dedo; su flanqueo es un peligro expresamente señalado.","question_family":"2026_RAZONAMIENTO","difficulty":"muy alta","kind":"texto","coverage_id":25007,"source_page":6,"old_correct_index":1,"old_stem_md5":"efdf7c0341ec44b55a7c70e047ec1b8c","source_evidence":"CEIS Guadalajara, Incendios de vegetación, página impresa 246: La prolongación estrecha conectada es un dedo; su flanqueo es un peligro expresamente señalado."},{"id":2939,"manual_page":"246","stem":"Un frente alargado presenta ramificaciones y sectores de velocidad desigual. ¿Qué combinación de factores explica su carácter irregular sin exigir que concurran todos?","options":["Cambios de viento, diferencias de combustible o pendientes irregulares, actuando solos o combinados.","Calma atmosférica, terreno plano y combustible homogéneo, actuando obligatoriamente juntos.","Viento predominante fijo y homogéneo, pendiente uniforme y combustible constante, todos necesarios.","Solo la existencia de focos secundarios, sin influencia de viento, relieve ni tipo de combustible."],"correct_index":0,"explanation":"El manual enumera viento variable, combustible heterogéneo y/o pendientes irregulares como determinantes de formas irregulares.","question_family":"2026_RAZONAMIENTO","difficulty":"muy alta","kind":"texto","coverage_id":25008,"source_page":6,"old_correct_index":0,"old_stem_md5":"e68bb09f65ca79b8062bf4489b4f5487","source_evidence":"CEIS Guadalajara, Incendios de vegetación, página impresa 246: El manual enumera viento variable, combustible heterogéneo y/o pendientes irregulares como determinantes de formas irregulares."},{"id":2941,"manual_page":"246","stem":"Entre las asociaciones de tipo de frente, viento y relieve, ¿qué interpretación de la morfología resulta INCORRECTA?","options":["Los incendios de forma circular se asocian a combustible homogéneo y ausencia de viento.","Los incendios irregulares se asocian a viento estable, relieve uniforme y combustible homogéneo.","Los incendios elípticos pueden avanzar sobre terreno plano con viento predominante.","Los incendios irregulares pueden asociarse a vientos variables y heterogeneidad del combustible."],"correct_index":1,"explanation":"La irregularidad no requiere las condiciones de uniformidad de la segunda opción.","question_family":"2026_INCORRECTA","difficulty":"muy alta","kind":"texto","coverage_id":25009,"source_page":6,"old_correct_index":1,"old_stem_md5":"7882132f76689731afc72ecbe4838cc8","source_evidence":"CEIS Guadalajara, Incendios de vegetación, página impresa 246: La irregularidad no requiere las condiciones de uniformidad de la segunda opción."},{"id":2942,"manual_page":"252","stem":"En un valle el aire circula longitudinalmente y se registran temperaturas diferentes a lo largo de su eje y respecto al aire exterior situado a igual altura. ¿Qué mecanismo explica mejor la corriente descrita?","options":["Una diferencia de presión vertical entre el fondo y la cumbre que produce exclusivamente vientos paralelos a las laderas.","La rotación del aire alrededor de la montaña, independiente de la presión y de las diferencias de temperatura.","Gradientes horizontales de presión asociados a contrastes térmicos a lo largo del valle o con el plano adyacente.","Un gradiente vertical de temperatura que elimina toda componente de circulación longitudinal del aire."],"correct_index":2,"explanation":"Los vientos de valle son paralelos al eje longitudinal y se producen por gradientes horizontales de presión debidos a diferencias térmicas.","question_family":"2026_RAZONAMIENTO","difficulty":"muy alta","kind":"texto","coverage_id":25010,"source_page":12,"old_correct_index":0,"old_stem_md5":"e1e403bae3165b627ad4117e77ef8f56","source_evidence":"CEIS Guadalajara, Incendios de vegetación, página impresa 252: Los vientos de valle son paralelos al eje longitudinal y se producen por gradientes horizontales de presión debidos a diferencias térmicas."},{"id":2943,"manual_page":"252","stem":"Una estación detecta una corriente paralela al fondo de un valle, no a la pendiente de una vertiente concreta. ¿Qué relación entre orientación y fuerza impulsora corresponde al fenómeno?","options":["Circulación paralela a la máxima pendiente, originada por diferencias de densidad entre sotavento y barlovento.","Circulación perpendicular al valle, originada por diferencias de presión vertical a lo largo de la vertiente.","Circulación paralela al eje del valle, originada por diferencias de presión vertical a lo largo del macizo.","Circulación paralela al eje del valle, originada por un gradiente horizontal de presión asociado a contrastes térmicos."],"correct_index":3,"explanation":"El texto distingue los vientos de valle longitudinales y sus gradientes horizontales de presión frente a los vientos de ladera.","question_family":"2026_RAZONAMIENTO","difficulty":"muy alta","kind":"texto","coverage_id":25011,"source_page":12,"old_correct_index":1,"old_stem_md5":"3f51241dd494552a5cd41f35a56cc137","source_evidence":"CEIS Guadalajara, Incendios de vegetación, página impresa 252: El texto distingue los vientos de valle longitudinales y sus gradientes horizontales de presión frente a los vientos de ladera."},{"id":2944,"manual_page":"252","stem":"Un incendio aparentemente controlado se encuentra en un valle durante el paso de la circulación nocturna descendente a la diurna ascendente. ¿Qué cambio exige atención especial?","options":["Puede reactivarse en pocos minutos y coincidir con ruptura de inversión térmica, menor estabilidad y rachas más intensas.","Solo puede reactivarse después de varios días porque los gradientes horizontales requieren un ciclo completo.","La inversión de sentido estabiliza necesariamente la atmósfera y suprime la aparición de rachas en el valle.","El cambio impide reactivaciones si el fuego estaba controlado porque desaparecen los gradientes de presión."],"correct_index":0,"explanation":"El manual advierte de reactivación rápida al pasar de descendente a ascendente, a veces con ruptura de inversión y aumento de rachas.","question_family":"2026_RAZONAMIENTO","difficulty":"muy alta","kind":"texto","coverage_id":25012,"source_page":12,"old_correct_index":2,"old_stem_md5":"b4de4ae66eb158a353ecb0a3fdd97024","source_evidence":"CEIS Guadalajara, Incendios de vegetación, página impresa 252: El manual advierte de reactivación rápida al pasar de descendente a ascendente, a veces con ruptura de inversión y aumento de rachas."},{"id":2946,"manual_page":"252","stem":"Durante la transición entre el flujo nocturno y el diurno a lo largo de un valle, ¿qué afirmación es INCORRECTA?","options":["La corriente diurna puede dirigirse hacia las partes altas del valle por efecto del calentamiento.","La inversión de dirección se acelera cuando la masa de aire que debe movilizarse es especialmente grande.","La corriente nocturna puede soplar valle abajo, invirtiendo el sentido diurno.","El paso de descendente a ascendente puede reactivar un incendio previamente controlado."],"correct_index":1,"explanation":"El manual indica expresamente que la inversión puede hacerse más lenta cuando se movilizan grandes masas de aire.","question_family":"2026_INCORRECTA","difficulty":"muy alta","kind":"texto","coverage_id":25013,"source_page":12,"old_correct_index":3,"old_stem_md5":"7fb4bc712d8a11d48499c89c21e5e2b3","source_evidence":"CEIS Guadalajara, Incendios de vegetación, página impresa 252: El manual indica expresamente que la inversión puede hacerse más lenta cuando se movilizan grandes masas de aire."},{"id":2948,"manual_page":"252","stem":"Una masa de aire muy extensa permanece circulando valle abajo tras comenzar el calentamiento diurno. ¿Qué explicación permite compatibilizar esa demora con el ciclo local descrito?","options":["La inversión exige necesariamente esperar hasta que el sol se oculte, cualquiera que sea la masa del aire.","Los vientos de valle cambian solo cuando desaparece la diferencia de presión horizontal durante varios días.","La movilización de grandes masas de aire puede retrasar la inversión desde el régimen descendente al ascendente.","La mayor masa de aire hace que el cambio de corriente resulte instantáneo por el aumento de presión vertical."],"correct_index":2,"explanation":"La inversión diurna/nocturna de viento de valle puede ser más lenta si deben movilizarse grandes masas de aire.","question_family":"2026_RAZONAMIENTO","difficulty":"muy alta","kind":"texto","coverage_id":25014,"source_page":12,"old_correct_index":1,"old_stem_md5":"e9488c7ace9402bda587e57e7eb5de05","source_evidence":"CEIS Guadalajara, Incendios de vegetación, página impresa 252: La inversión diurna/nocturna de viento de valle puede ser más lenta si deben movilizarse grandes masas de aire."},{"id":2950,"manual_page":"252","stem":"Dos observadores informan de corrientes distintas: una sigue el eje principal del valle y la otra sube por una ladera lateral. ¿Qué característica permite distinguir específicamente la primera?","options":["Se mueve conforme a la inclinación de la vertiente por diferencias térmicas con el aire exterior de la capa límite.","Se mueve perpendicular a las curvas del valle y se origina únicamente por enfriamiento nocturno del suelo.","Se mueve hacia la cumbre por convección y su velocidad característica debe situarse entre 6 y 13 km/h.","Se mueve paralela al eje longitudinal del valle debido a gradientes horizontales de presión."],"correct_index":3,"explanation":"El viento de valle se identifica por dirección longitudinal y gradiente horizontal; el de ladera sigue la inclinación de las vertientes.","question_family":"2026_RAZONAMIENTO","difficulty":"muy alta","kind":"texto","coverage_id":25015,"source_page":12,"old_correct_index":2,"old_stem_md5":"1968de62b510f49a6f10ed00312ee073","source_evidence":"CEIS Guadalajara, Incendios de vegetación, página impresa 252: El viento de valle se identifica por dirección longitudinal y gradiente horizontal; el de ladera sigue la inclinación de las vertientes."},{"id":2952,"manual_page":"252","stem":"El manual describe dos orígenes de los gradientes térmicos capaces de impulsar vientos longitudinales de valle. ¿Qué pareja reproduce correctamente ambos?","options":["Diferencias térmicas a lo largo del valle y entre su aire y el del plano adyacente a igual altitud.","Diferencias térmicas solo entre la base y la cima y entre el aire marítimo y el aire terrestre.","Diferencias térmicas solo entre dos laderas opuestas y entre aire húmedo y seco a distinta altitud.","Diferencias térmicas solo entre sotavento y barlovento y entre capas de inversión a diferente altura."],"correct_index":0,"explanation":"Los gradientes horizontales pueden proceder del eje del valle o del contraste con aire del plano adyacente a igual altura.","question_family":"2026_RAZONAMIENTO","difficulty":"muy alta","kind":"texto","coverage_id":25016,"source_page":12,"old_correct_index":0,"old_stem_md5":"9b4b2ea79f983833ed0c53cb484ec0f7","source_evidence":"CEIS Guadalajara, Incendios de vegetación, página impresa 252: Los gradientes horizontales pueden proceder del eje del valle o del contraste con aire del plano adyacente a igual altura."},{"id":2953,"manual_page":"252","stem":"Para identificar el régimen de valle frente al de ladera por sus velocidades, ¿qué asociación es INCORRECTA?","options":["El viento descendente de ladera presenta un intervalo orientativo de 1 a 10 km/h.","Los vientos longitudinales de valle se caracterizan en el manual por un intervalo de 1 a 10 km/h.","El viento ascendente de ladera presenta un intervalo orientativo de 6 a 13 km/h.","Los vientos de valle pueden invertir su dirección entre el día y la noche."],"correct_index":1,"explanation":"El intervalo 1–10 km/h se da para viento descendente de ladera, no como rango universal de todo viento de valle.","question_family":"2026_INCORRECTA","difficulty":"muy alta","kind":"texto","coverage_id":25017,"source_page":12,"old_correct_index":3,"old_stem_md5":"d2153f1595d5e3f5be27cdfa6fe8b5c7","source_evidence":"CEIS Guadalajara, Incendios de vegetación, página impresa 252: El intervalo 1–10 km/h se da para viento descendente de ladera, no como rango universal de todo viento de valle."},{"id":2954,"manual_page":"251","stem":"Una dotación trabaja en una ladera soleada a media mañana y detecta flujo hacia la cumbre con turbulencia. ¿Qué relación de velocidad y régimen coincide con el viento local característico?","options":["Descendente, de 1–10 km/h y laminado sin turbulencia, con máximos en la parte baja.","Ascendente, de 1–10 km/h y laminado sin turbulencia, con intensidad uniforme hasta la cima.","Ascendente, de 6–13 km/h, posible turbulencia cuesta arriba y mayor intensidad en cumbres.","Descendente, de 6–13 km/h, con turbulencia preferente durante las horas nocturnas."],"correct_index":2,"explanation":"Los vientos ascendentes de ladera diurnos suelen moverse a 6–13 km/h, con turbulencias cuesta arriba y fuerza en las cumbres.","question_family":"2026_RAZONAMIENTO","difficulty":"muy alta","kind":"texto","coverage_id":25018,"source_page":11,"old_correct_index":1,"old_stem_md5":"4c0420766aaf07220f454974bc5002c2","source_evidence":"CEIS Guadalajara, Incendios de vegetación, página impresa 251: Los vientos ascendentes de ladera diurnos suelen moverse a 6–13 km/h, con turbulencias cuesta arriba y fuerza en las cumbres."},{"id":2955,"manual_page":"251","stem":"Al comenzar la insolación, una ladera se calienta antes que el aire libre situado a la misma altitud. ¿Qué secuencia física justifica el viento que aparece sobre ella?","options":["El aire de la ladera se enfría, aumenta su densidad y comienza un movimiento ascendente por gravedad.","El aire libre se vuelve más ligero que el adyacente a la ladera y arrastra este último hacia el fondo del valle.","La ladera calienta por igual todas las capas de aire, anulando el contraste de densidad y provocando calma.","El aire junto a la ladera se calienta, resulta más liviano que el aire a igual altura y circula cuesta arriba."],"correct_index":3,"explanation":"El calentamiento diferencial vuelve más ligero al aire adyacente a la ladera y origina el viento ascendente.","question_family":"2026_RAZONAMIENTO","difficulty":"muy alta","kind":"texto","coverage_id":25019,"source_page":11,"old_correct_index":2,"old_stem_md5":"66ad07d8a4ef947f8b1b2e074822e7fc","source_evidence":"CEIS Guadalajara, Incendios de vegetación, página impresa 251: El calentamiento diferencial vuelve más ligero al aire adyacente a la ladera y origina el viento ascendente."},{"id":2956,"manual_page":"252","stem":"Una ladera queda en sombra a media tarde pese a que aún existe luz solar en otras vertientes. ¿Qué conclusión se ajusta a la duración orientativa del viento de ladera ascendente?","options":["Puede cesar al quedar la vertiente en sombra; el intervalo diurno orientativo es de 08:00 a 18:00.","Debe mantenerse hasta las 05:00 del día siguiente porque el intervalo del ascendente incluye la madrugada.","Solo puede interrumpirse a las 18:00 exactas, ya que el sombreado no modifica el ciclo local.","Debe invertirse al mediodía porque la corriente ascendente se limita a las primeras horas de luz."],"correct_index":0,"explanation":"La duración indicada para ascendentes es 08:00–18:00 aproximadamente o hasta la sombra de la ladera.","question_family":"2026_RAZONAMIENTO","difficulty":"muy alta","kind":"texto","coverage_id":25020,"source_page":12,"old_correct_index":0,"old_stem_md5":"67f2485c93515fbb6b8a58fb7e0547d8","source_evidence":"CEIS Guadalajara, Incendios de vegetación, página impresa 252: La duración indicada para ascendentes es 08:00–18:00 aproximadamente o hasta la sombra de la ladera."},{"id":2957,"manual_page":"252","stem":"El viento nocturno de ladera pasa a soplar cuesta arriba en las primeras horas del día, mientras hay un incendio controlado. ¿Qué evolución atmosférica y operativa menciona el manual?","options":["Refuerzo de la inversión térmica, mayor estabilidad y desaparición de las rachas antes de cualquier reactivación.","Posible ruptura de la inversión térmica, pérdida de estabilidad, rachas más fuertes y reactivación del fuego en minutos.","Ausencia de cambios en estabilidad por tratarse de flujos exclusivamente paralelos al eje del valle.","Descenso forzoso de la temperatura sobre la ladera, sin cambios en el régimen de viento ni la combustión."],"correct_index":1,"explanation":"La transición descendente a ascendente puede romper la inversión, reducir estabilidad, aumentar rachas y reactivar el fuego.","question_family":"2026_RAZONAMIENTO","difficulty":"muy alta","kind":"texto","coverage_id":25021,"source_page":12,"old_correct_index":2,"old_stem_md5":"57a1898f0cc390560061c2d9497257d9","source_evidence":"CEIS Guadalajara, Incendios de vegetación, página impresa 252: La transición descendente a ascendente puede romper la inversión, reducir estabilidad, aumentar rachas y reactivar el fuego."},{"id":2958,"manual_page":"251","stem":"En una ladera, durante la madrugada se observa movimiento de aire hacia el valle. Se desea diferenciarlo del viento diurno ascendente mediante horario, velocidad y turbulencia. ¿Qué terna es la correcta?","options":["08:00–18:00, 6–13 km/h y posibles turbulencias cuesta arriba.","18:00–05:00, 6–13 km/h y rachas intensas hacia la cumbre.","18:00–05:00, 1–10 km/h y flujo en láminas sin turbulencia.","08:00–18:00, 1–10 km/h y flujo laminar sin turbulencia."],"correct_index":2,"explanation":"El descendente nocturno se describe entre 18:00 y 05:00, 1–10 km/h y en láminas sin turbulencia.","question_family":"2026_RAZONAMIENTO","difficulty":"muy alta","kind":"texto","coverage_id":25022,"source_page":11,"old_correct_index":1,"old_stem_md5":"4e864e944e574916a6f69494d78d61f6","source_evidence":"CEIS Guadalajara, Incendios de vegetación, página impresa 251: El descendente nocturno se describe entre 18:00 y 05:00, 1–10 km/h y en láminas sin turbulencia."},{"id":2959,"manual_page":"253","stem":"Un viento descendente nocturno es generalmente débil, pero adquiere gran intensidad en una ladera concreta. ¿Qué condiciones del terreno justificarían esa intensificación?","options":["Pendiente suave con vegetación heterogénea y ausencia de encauzamiento por el relieve.","Pendiente irregular con suelo muy rugoso y desaparición del canal de circulación del valle.","Vertiente sombreada que recibe calentamiento diurno y presenta inversión térmica permanente.","Pendiente fuerte y lisa, incluso con hielo o nieve, o canalización de la corriente por el valle."],"correct_index":3,"explanation":"Una pendiente fuerte y lisa, especialmente helada o nevada, y el encauzamiento del valle refuerzan el flujo nocturno.","question_family":"2026_RAZONAMIENTO","difficulty":"muy alta","kind":"texto","coverage_id":25023,"source_page":13,"old_correct_index":0,"old_stem_md5":"b4d5211ce1ddf272df1bad3520903aaf","source_evidence":"CEIS Guadalajara, Incendios de vegetación, página impresa 253: Una pendiente fuerte y lisa, especialmente helada o nevada, y el encauzamiento del valle refuerzan el flujo nocturno."},{"id":2960,"manual_page":"253","stem":"Al anochecer, el aire superficial de una vertiente pierde calor por radiación. ¿Qué secuencia explica el comienzo de una corriente descendente?","options":["El aire se enfría, aumenta su densidad y desciende por gravedad siguiendo la pendiente hacia el valle.","El aire se enfría, disminuye su densidad y asciende por gravedad hacia la divisoria.","El aire se calienta por radiación nocturna, aumenta su densidad y asciende por la pendiente.","El aire conserva densidad constante y desciende únicamente por un viento dominante cálido."],"correct_index":0,"explanation":"El enfriamiento radiativo nocturno incrementa la densidad del aire, que baja por gravedad siguiendo la ladera.","question_family":"2026_RAZONAMIENTO","difficulty":"muy alta","kind":"texto","coverage_id":25024,"source_page":13,"old_correct_index":1,"old_stem_md5":"f7a582a8ca37f77d18c926a67d30fc32","source_evidence":"CEIS Guadalajara, Incendios de vegetación, página impresa 253: El enfriamiento radiativo nocturno incrementa la densidad del aire, que baja por gravedad siguiendo la ladera."},{"id":2961,"manual_page":"251","stem":"En un cambio del viento de ladera entre el régimen nocturno y el diurno, ¿qué caracterización es INCORRECTA?","options":["El ascendente es predominantemente diurno y puede presentar turbulencias cuesta arriba.","El descendente nocturno presenta como régimen característico 6–13 km/h y turbulencias cuesta arriba.","El descendente puede discurrir en láminas sin turbulencia durante la noche.","El ascendente diurno puede ser más intenso en las cumbres y cesar al quedar la ladera en sombra."],"correct_index":1,"explanation":"Las velocidades 6–13 km/h y la turbulencia cuesta arriba caracterizan al ascendente; el descendente presenta 1–10 km/h y flujo laminar.","question_family":"2026_INCORRECTA","difficulty":"muy alta","kind":"texto","coverage_id":25025,"source_page":11,"old_correct_index":3,"old_stem_md5":"da8c9627e192286caec3d69fbdbd6dfd","source_evidence":"CEIS Guadalajara, Incendios de vegetación, página impresa 251: Las velocidades 6–13 km/h y la turbulencia cuesta arriba caracterizan al ascendente; el descendente presenta 1–10 km/h y flujo laminar."},{"id":2962,"manual_page":"253","stem":"La documentación registra episodios de viento tipo foehn con condiciones extremas y una duración usual limitada. ¿Qué combinación de velocidad máxima observada, humedad relativa y duración describe?","options":["Hasta 145 km/h, humedad relativa del 30 % y duración habitual inferior a tres días.","Hasta 125 km/h, humedad relativa del 3 % y duración habitual superior a tres días.","Hasta 145 km/h, humedad relativa del 3 % y duración habitual que no suele superar tres días.","Hasta 145 km/h, humedad relativa del 3 % y duración habitual necesariamente superior a una semana."],"correct_index":2,"explanation":"El manual cita registros hasta 145 km/h, 3 % de humedad relativa y duración por lo general no superior a tres días.","question_family":"2026_RAZONAMIENTO","difficulty":"muy alta","kind":"texto","coverage_id":25026,"source_page":13,"old_correct_index":0,"old_stem_md5":"c7fd82b161f20dcf24ff8b0a5aa77b03","source_evidence":"CEIS Guadalajara, Incendios de vegetación, página impresa 253: El manual cita registros hasta 145 km/h, 3 % de humedad relativa y duración por lo general no superior a tres días."},{"id":2963,"manual_page":"253","stem":"Los nombres regionales de los vientos tipo foehn pueden inducir confusión. ¿Qué asociación territorial recoge el manual?","options":["Poniente en el sur de Chile; Austrum en Murcia; Puelche en Rumanía.","Poniente en Rumanía; Austrum en la Comunidad Valenciana; Puelche en Murcia.","Poniente en la Comunidad Valenciana y Murcia; Austrum en el sur de Chile; Puelche en Rumanía.","Poniente en la Comunidad Valenciana y Murcia; Austrum en Rumanía; Puelche en el sur de Chile."],"correct_index":3,"explanation":"El CEIS asocia Poniente a Comunidad Valenciana y Murcia, Austrum a Rumanía y Puelche al sur de Chile.","question_family":"2026_RAZONAMIENTO","difficulty":"muy alta","kind":"texto","coverage_id":25027,"source_page":13,"old_correct_index":2,"old_stem_md5":"c1d7e30a4990fd2eb5b32b301e875a79","source_evidence":"CEIS Guadalajara, Incendios de vegetación, página impresa 253: El CEIS asocia Poniente a Comunidad Valenciana y Murcia, Austrum a Rumanía y Puelche al sur de Chile."},{"id":2964,"manual_page":"253","stem":"Una masa de aire asciende por barlovento, pierde parte de su humedad al superar una cordillera y desciende por la vertiente opuesta. ¿Qué efecto constituye el riesgo forestal fundamental del flujo descrito?","options":["Calentamiento y desecación intensos por viento descendente tipo foehn, que pueden favorecer propagaciones incontrolables.","Enfriamiento y humectación intensos por viento descendente tipo foehn, que reducen la continuidad del combustible.","Ascenso de aire frío y húmedo por sotavento que mantiene hidratada la vegetación próxima a la costa.","Circulación ascendente y húmeda por ambas vertientes, sin relación con el estado de humedad del combustible."],"correct_index":0,"explanation":"El foehn es viento cálido, seco y descendente; al desecar rápidamente la vegetación aumenta el peligro de propagación.","question_family":"2026_RAZONAMIENTO","difficulty":"muy alta","kind":"texto","coverage_id":25028,"source_page":13,"old_correct_index":0,"old_stem_md5":"3a08b180e3a17cd59b88324b3220165b","source_evidence":"CEIS Guadalajara, Incendios de vegetación, página impresa 253: El foehn es viento cálido, seco y descendente; al desecar rápidamente la vegetación aumenta el peligro de propagación."},{"id":2965,"manual_page":"253","stem":"Tras atravesar una cordillera, un viento terral alcanza vegetación costera que suele crecer bajo elevada humedad ambiental. ¿Qué circunstancia agrava el riesgo descrito?","options":["La vegetación permanece adaptada a sequedad permanente y no acusa cambios bruscos al llegar aire seco.","La vegetación habituada a humedad relativa alta puede desecarse muy rápidamente bajo el viento terral.","La vegetación absorbe necesariamente humedad adicional de los vientos descendentes tras la condensación de barlovento.","La vegetación se conserva húmeda en sotavento porque el aire descendente aumenta su humedad relativa."],"correct_index":1,"explanation":"El manual destaca la rápida desecación de la vegetación costera habituada a humedad ambiental al llegar viento terral seco.","question_family":"2026_RAZONAMIENTO","difficulty":"muy alta","kind":"texto","coverage_id":25029,"source_page":13,"old_correct_index":0,"old_stem_md5":"13e5ceefe3241b7ee016bb80812c2628","source_evidence":"CEIS Guadalajara, Incendios de vegetación, página impresa 253: El manual destaca la rápida desecación de la vegetación costera habituada a humedad ambiental al llegar viento terral seco."}],"graphics":[{"id":2967,"manual_page":"246","stem":"En el croquis se observan dos superficies sin quemar: una entre una prolongación estrecha conectada y el cuerpo principal, y otra totalmente encerrada por el perímetro. Si una dotación progresa hacia la prolongación, ¿qué identificación y riesgo resultan correctos?","options":["La bolsa es el área quemada exterior; la isla es el foco secundario y el dedo no comunica con el perímetro.","La bolsa es el área no quemada entre un dedo y el incendio; la isla es combustible intacto interior y el dedo puede flanquear personal.","La bolsa es la prolongación estrecha incendiada; la isla es un entrante abierto y el foco secundario flanquea necesariamente.","La bolsa está completamente encerrada; la isla conecta con el exterior y el dedo es una zona sin combustible."],"correct_index":1,"explanation":"El dibujo distingue dedo conectado, bolsa no quemada entre dedo y cuerpo, isla no quemada interior y focos secundarios exteriores.","question_family":"2026_RAZONAMIENTO","difficulty":"muy alta","kind":"grafica","coverage_id":24985,"source_page":6,"old_correct_index":0,"old_stem_md5":"57cc25c7f21348048581060be889a3ab","source_evidence":"CEIS Guadalajara, Incendios de vegetación, página impresa 246: El dibujo distingue dedo conectado, bolsa no quemada entre dedo y cuerpo, isla no quemada interior y focos secundarios exteriores.","graphic_key":"T43-GRAF-01","original_file":"Screenshot_20260924-122747~2.jpg"},{"id":2968,"manual_page":"246","stem":"La figura representa cinco formas (a–e). En un terreno plano de combustible homogéneo, la aparición de viento de dirección dominante altera un frente inicialmente circular. ¿Qué clasificación inicial y final resulta coherente con los dibujos?","options":["Inicial (a) circular; final (c) irregular por aparecer cualquier viento, aun constante.","Inicial (b) elíptica; final (a) circular por aumentar la velocidad del viento dominante.","Inicial (a) circular; final (b) elíptica; las formas (c–e) permiten variaciones de viento, combustible o relieve.","Inicial (c) irregular; final (b) elíptica; las formas (d–e) exigen siempre ausencia absoluta de viento."],"correct_index":2,"explanation":"El panel (a) corresponde a calma y circular; (b) viento predominante y elíptica; (c–e) a irregularidad.","question_family":"2026_RAZONAMIENTO","difficulty":"muy alta","kind":"grafica","coverage_id":25000,"source_page":6,"old_correct_index":2,"old_stem_md5":"c4bc3e0fa2501c8d737d5ab5e0a08a73","source_evidence":"CEIS Guadalajara, Incendios de vegetación, página impresa 246: El panel (a) corresponde a calma y circular; (b) viento predominante y elíptica; (c–e) a irregularidad.","graphic_key":"T43-GRAF-02","original_file":"Screenshot_20260924-122747~3.jpg"},{"id":2969,"manual_page":"252","stem":"En los dos paneles de vientos de valle, las flechas del día ascienden siguiendo el eje principal y las de la noche descienden. Un incendio permanece cerca de la salida inferior del valle al cambiar el régimen. ¿Cuál es la interpretación correcta?","options":["Son vientos de ladera paralelos a cada vertiente y se invierten por diferencias verticales de presión exclusivamente.","Son vientos de valle que ascienden de noche y descienden de día con inversión instantánea cualquiera que sea la masa.","Son brisas marinas porque la diferencia entre agua y tierra gobierna las flechas paralelas al valle.","Son vientos de valle impulsados por gradientes horizontales de presión y la inversión puede retardarse con grandes masas de aire."],"correct_index":3,"explanation":"Las flechas longitudinales identifican viento de valle; el manual atribuye su movimiento a gradientes horizontales de presión.","question_family":"2026_RAZONAMIENTO","difficulty":"muy alta","kind":"grafica","coverage_id":25012,"source_page":12,"old_correct_index":1,"old_stem_md5":"ef555f6f34de4b2c238da2807f2fa8b6","source_evidence":"CEIS Guadalajara, Incendios de vegetación, página impresa 252: Las flechas longitudinales identifican viento de valle; el manual atribuye su movimiento a gradientes horizontales de presión.","graphic_key":"T43-GRAF-03","original_file":"Screenshot_20260924-122831-display-0.png~2.jpg"},{"id":2970,"manual_page":"252","stem":"La imagen separa corrientes diurnas ascendentes de ladera y nocturnas descendentes. Una dotación afronta el cambio del panel nocturno al diurno mientras el foco está controlado. ¿Qué escenario corresponde a la transición?","options":["Paso a corriente ascendente de 6–13 km/h, posible turbulencia, pérdida de estabilidad y reactivación rápida del fuego.","Paso a corriente descendente de 1–10 km/h, flujo laminar y refuerzo generalizado de la inversión térmica.","Paso a corriente ascendente de 1–10 km/h, laminación sin turbulencia y supresión de rachas locales.","Paso a corriente descendente de 6–13 km/h, intensificación solo nocturna de vientos en cumbres."],"correct_index":0,"explanation":"El panel diurno ilustra la corriente ascendente; el manual cita 6–13 km/h, turbulencias y posible ruptura de inversión y reactivación.","question_family":"2026_RAZONAMIENTO","difficulty":"muy alta","kind":"grafica","coverage_id":25021,"source_page":12,"old_correct_index":3,"old_stem_md5":"c96a0e7c8127bd79650a4b2b335ef6eb","source_evidence":"CEIS Guadalajara, Incendios de vegetación, página impresa 252: El panel diurno ilustra la corriente ascendente; el manual cita 6–13 km/h, turbulencias y posible ruptura de inversión y reactivación.","graphic_key":"T43-GRAF-04","original_file":"Screenshot_20260924-122843-display-0.png~2.jpg"},{"id":2971,"manual_page":"253","stem":"En el esquema orográfico de la figura, una masa húmeda asciende por la vertiente izquierda, condensa cerca de la divisoria y desciende por la derecha. Un foco aparece en el pie derecho. ¿Qué mecanismo explica el peligro principal?","options":["Sotavento húmedo, por condensación durante el descenso, con enfriamiento de la vegetación del lado derecho.","Sotavento seco, porque el aire perdió humedad en barlovento y desciende cálido, desecando el combustible de la derecha.","Barlovento seco, porque el aire que asciende no se enfría y humedece el combustible de la derecha.","Barlovento húmedo, porque el aire que desciende de la divisoria aumenta las precipitaciones en el pie derecho."],"correct_index":1,"explanation":"La figura muestra barlovento ascendente con condensación y sotavento descendente cálido-seco con sombra de lluvia.","question_family":"2026_RAZONAMIENTO","difficulty":"muy alta","kind":"grafica","coverage_id":25028,"source_page":13,"old_correct_index":0,"old_stem_md5":"cf0e0f41928a5b231dd62b4e3efa19e3","source_evidence":"CEIS Guadalajara, Incendios de vegetación, página impresa 253: La figura muestra barlovento ascendente con condensación y sotavento descendente cálido-seco con sombra de lluvia.","graphic_key":"T43-GRAF-05","original_file":"Screenshot_20260924-122900-display-0.png~2.jpg"}]};
